--
-- Table structure for table `rental_contracts`
--

DROP TABLE IF EXISTS `rental_contracts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rental_contracts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `parent_contract_id` bigint unsigned DEFAULT NULL,
  `premise_id` bigint unsigned NOT NULL,
  `submitted_by_user_id` bigint unsigned DEFAULT NULL,
  `no_fail_rujukan` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Contoh: AADK/BKP/PB 200-3/02',
  `tarikh_mula` date NOT NULL,
  `tarikh_tamat` date NOT NULL,
  `kadar_sewa_bulanan` decimal(10,2) NOT NULL DEFAULT '0.00',
  `keluasan_mp` decimal(10,2) DEFAULT NULL,
  `status_aktif` enum('aktif','tamat_tempoh','dalam_proses','batal') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'aktif',
  `peringkat_proses` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Contoh: Semakan PUU, Lulus BPH, Menunggu MOF',
  `tarikh_surat_niat` date DEFAULT NULL COMMENT 'Tarikh PTJ hantar surat niat sambung',
  `catatan_hq` text COLLATE utf8mb4_unicode_ci,
  `remark` text COLLATE utf8mb4_unicode_ci,
  `workflow_tahap` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'menunggu_semakan_negeri' COMMENT 'Aliran permohonan: menunggu_balasan_ptj | menunggu_semakan_negeri',
  `semakan_count` int unsigned NOT NULL DEFAULT '0',
  `kategori_permohonan` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tarikh_mula_tawaran` date DEFAULT NULL,
  `sah_sehingga` date DEFAULT NULL,
  `admin_proceed_progress` json DEFAULT NULL,
  `delete_reason` text COLLATE utf8mb4_unicode_ci,
  `deleted_by_user_id` bigint unsigned DEFAULT NULL,
  `withdrawal_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `withdrawal_reason` text COLLATE utf8mb4_unicode_ci,
  `withdrawal_requested_at` timestamp NULL DEFAULT NULL,
  `withdrawal_requested_by_user_id` bigint unsigned DEFAULT NULL,
  `withdrawal_resolved_at` timestamp NULL DEFAULT NULL,
  `withdrawal_resolved_by_user_id` bigint unsigned DEFAULT NULL,
  `withdrawal_resolution_note` text COLLATE utf8mb4_unicode_ci,
  `hq_approved_at` timestamp NULL DEFAULT NULL,
  `hq_jrp_checklist` json DEFAULT NULL,
  `negeri_draft_acknowledgements` json DEFAULT NULL,
  `hq_draft_acknowledgements` json DEFAULT NULL,
  `negeri_mati_setem_acknowledgements` json DEFAULT NULL,
  `superseded_at` timestamp NULL DEFAULT NULL,
  `superseded_by_contract_id` bigint unsigned DEFAULT NULL,
  `admin_negeri_user_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rental_contracts_premise_id_foreign` (`premise_id`),
  KEY `rental_contracts_tarikh_tamat_index` (`tarikh_tamat`),
  KEY `rental_contracts_status_aktif_index` (`status_aktif`),
  KEY `rental_contracts_submitted_by_user_id_foreign` (`submitted_by_user_id`),
  KEY `rental_contracts_deleted_by_user_id_foreign` (`deleted_by_user_id`),
  KEY `rental_contracts_withdrawal_requested_by_user_id_foreign` (`withdrawal_requested_by_user_id`),
  KEY `rental_contracts_withdrawal_resolved_by_user_id_foreign` (`withdrawal_resolved_by_user_id`),
  KEY `rental_contracts_admin_negeri_user_id_foreign` (`admin_negeri_user_id`),
  KEY `rental_contracts_parent_contract_id_foreign` (`parent_contract_id`),
  KEY `rental_contracts_superseded_by_contract_id_foreign` (`superseded_by_contract_id`),
  CONSTRAINT `rental_contracts_admin_negeri_user_id_foreign` FOREIGN KEY (`admin_negeri_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rental_contracts_deleted_by_user_id_foreign` FOREIGN KEY (`deleted_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rental_contracts_parent_contract_id_foreign` FOREIGN KEY (`parent_contract_id`) REFERENCES `rental_contracts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rental_contracts_premise_id_foreign` FOREIGN KEY (`premise_id`) REFERENCES `premises` (`id`) ON DELETE CASCADE,
  CONSTRAINT `rental_contracts_submitted_by_user_id_foreign` FOREIGN KEY (`submitted_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rental_contracts_superseded_by_contract_id_foreign` FOREIGN KEY (`superseded_by_contract_id`) REFERENCES `rental_contracts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rental_contracts_withdrawal_requested_by_user_id_foreign` FOREIGN KEY (`withdrawal_requested_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rental_contracts_withdrawal_resolved_by_user_id_foreign` FOREIGN KEY (`withdrawal_resolved_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

